import { readFile, writeFile, readdir } from 'node:fs/promises';
import { createHash } from 'node:crypto';
// Authorize only the exact Astro island bootstraps generated by this build.
const hashes = new Set();
const styleHashes = new Set();
async function scan(dir) {
  for (const entry of await readdir(dir, {withFileTypes:true})) {
    const path = `${dir}/${entry.name}`;
    if (entry.isDirectory()) await scan(path);
    else if (entry.name.endsWith('.html')) {
      const html = await readFile(path,'utf8');
      for (const match of html.matchAll(/<style\b[^>]*>([\s\S]*?)<\/style>/gi)) {
        styleHashes.add(`'sha256-${createHash('sha256').update(match[1]).digest('base64')}'`);
      }
      for (const match of html.matchAll(/<script\b([^>]*)>([\s\S]*?)<\/script>/gi)) {
        if (!/\bsrc\s*=/.test(match[1]) && match[2].trim()) hashes.add(`'sha256-${createHash('sha256').update(match[2]).digest('base64')}'`);
      }
    }
  }
}
await scan('dist');
const headers = (await readFile('public/_headers','utf8')).replace("script-src 'self'",`script-src 'self' ${[...hashes].join(' ')}`).replace("style-src 'self'", `style-src 'self' ${[...styleHashes].join(' ')}; style-src-attr 'unsafe-inline'`);
await writeFile('dist/_headers',headers);
console.log(`CSP: ${hashes.size} exact inline script hashes; Radix layout style attributes enabled.`);
